package com.print.kiosk.controller;
import com.print.kiosk.dto.request.*;import com.print.kiosk.dto.response.*;import com.print.kiosk.service.interfaces.*;import com.print.kiosk.service.model.FileDownloadPayload;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/agent/requests") public class AgentRequestProcessingController{private final RequestProcessingService processing;private final CashPaymentService payments;public AgentRequestProcessingController(RequestProcessingService p,CashPaymentService c){processing=p;payments=c;}@PostMapping("/{id}/cash-pin")public ResponseEntity<CashPinResponse> pin(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(payments.generatePin(id,aid(jwt)));}@GetMapping("/{id}")public ResponseEntity<ProcessingRequestResponse> details(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(processing.getDetails(id,aid(jwt)));}@GetMapping("/{id}/files/{fileId}/download")public ResponseEntity<byte[]> download(@PathVariable Long id,@PathVariable Long fileId,@AuthenticationPrincipal Jwt jwt,HttpServletRequest request){FileDownloadPayload p=processing.downloadFile(id,fileId,aid(jwt),request.getRemoteAddr());ContentDisposition cd=ContentDisposition.attachment().filename(p.fileName(),StandardCharsets.UTF_8).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(p.mimeType())).header(HttpHeaders.CONTENT_DISPOSITION,cd.toString()).contentLength(p.content().length).body(p.content());}@PostMapping("/{id}/start-printing")public ResponseEntity<RequestActionResponse> start(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok(processing.startPrinting(id,aid(jwt)));}@PostMapping("/{id}/complete")public ResponseEntity<RequestActionResponse> complete(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody CompletePrintingRequest r){return ResponseEntity.ok(processing.complete(id,aid(jwt),r));}@PostMapping("/{id}/release")public ResponseEntity<RequestActionResponse> release(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ReleaseClaimRequest r){return ResponseEntity.ok(processing.release(id,aid(jwt),r));}@PostMapping("/{id}/pause")public ResponseEntity<RequestActionResponse> pause(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody PauseRequestRequest r){return ResponseEntity.ok(processing.pause(id,aid(jwt),r));}@PostMapping("/{id}/problem")public ResponseEntity<RequestActionResponse> problem(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ReportProblemRequest r){return ResponseEntity.ok(processing.reportProblem(id,aid(jwt),r));}@PostMapping("/{id}/cancel")public ResponseEntity<RequestActionResponse> cancel(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody CancelProcessingRequest r){return ResponseEntity.ok(processing.cancel(id,aid(jwt),r));}@PostMapping("/{id}/reopen")public ResponseEntity<RequestActionResponse> reopen(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ReopenRequestRequest r){return ResponseEntity.ok(processing.reopenByAgent(id,aid(jwt),r));}private Long aid(Jwt jwt){Number n=jwt.getClaim("accountId");if(n==null)throw new IllegalArgumentException("Authenticated account ID is missing");return n.longValue();}}